import { chromium } from 'playwright';
const browser=await chromium.launch({headless:true});
const page=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});
const errors=[];page.on('pageerror',e=>errors.push(String(e)));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
await page.route('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2*',route=>route.fulfill({status:200,contentType:'application/javascript',body:`(()=>{class FakeChannel{constructor(topic){this.topic=topic;this.handlers=[]}on(type,filter,cb){this.handlers.push({event:filter.event,cb});return this}subscribe(cb){setTimeout(()=>cb&&cb('SUBSCRIBED'),0);return this}async httpSend(){return {status:'ok'}}}window.supabase={createClient(){return{channel(t){return new FakeChannel(t)},async removeChannel(){return true}}}}})();`}));
await page.goto('http://127.0.0.1:4173/calculator/',{waitUntil:'load',timeout:20000});
for(const d of ['5','9','6','3'])await page.locator(`#calc [data-v="${d}"]`).click();await page.locator('#calc [data-a="eq"]').click();await page.waitForTimeout(250);
if(!(await page.locator('#home.screen.active').count()))throw new Error('Unlock failed');
await page.locator('.calculator-phone-launch').first().waitFor({state:'visible',timeout:6000});await page.locator('.calculator-phone-launch').first().click({timeout:3000});if(!(await page.locator('#app.screen.active .phone-app-page').count()))throw new Error('Phone failed');console.log('PHONE_PASS');
await page.locator('#app .ios-back').first().click();await page.locator('.calculator-contacts-launch').first().click({timeout:3000});if(!((await page.locator('#app h2').first().textContent())||'').includes('Contacts'))throw new Error('Contacts failed');console.log('CONTACTS_PASS');
await page.locator('#app .ios-back').first().click();await page.locator('.secret-message-launch').first().click({timeout:3000});if(!((await page.locator('#app h2').first().textContent())||'').includes('Secret Message'))throw new Error('Messages failed');console.log('MESSAGES_PASS');
await page.evaluate(()=>{const o=document.createElement('div');o.id='calcCallOverlay';o.className='calc-call-overlay';o.innerHTML='<div class="call-small">Incoming Calculator call</div><button id="decline">Decline</button><button id="accept">Accept</button>';document.body.append(o)});await page.waitForTimeout(700);
const ringResponsive=await page.evaluate(()=>new Promise(r=>setTimeout(()=>r(true),80)));if(!ringResponsive)throw new Error('Ringtone blocked main thread');await page.locator('#accept').click({timeout:2000});console.log('RINGTONE_UI_PASS');
await page.evaluate(()=>document.getElementById('calcCallOverlay')?.remove());
if(errors.length)throw new Error(errors.join(' | '));console.log('CALCULATOR_V27_SMOKE_TEST_PASS');await browser.close();